        if (!epan_init(register_all_protocols, register_all_protocol_handoffs, NULL, NULL))
        {
                ret = EPAN_INIT_FAIL;
                goto clean_exit;
        }

        /* Load libwireshark settings from the current profile. */
        prefs_p = epan_load_settings();

        if (!color_filters_init(&err_msg, NULL))
