com_token_start = 0;
        com_token_length = 0;

        if (data == NULL)
                return NULL;

        /* skip whitespace */
skipwhite:
        while (TRUE) {
                c = *data;
                if (c == '\0')
                        return NULL;    /* end of file; */
                if ((c != ' ') && (!g_ascii_iscntrl(c)))
                    break;
                data++;
                com_token_start++;
        }

        /* skip // comments */
        if ((c=='/') && (data[1]=='/')) {
                while (*data && *data != '\n'){
                        data++;
                        com_token_start++;
                }
                goto skipwhite;
        }

        /* handle quoted strings specially */
        if (c == '\"') {
                data++;
                com_token_start++;
                while (TRUE) {
                        c = *data++;
                        if ((c=='\"') || (c=='\0')) {
                                com_token[len] = '\0';
                                return data;
                        }
                        com_token[len] = c;
                        len++;
                        com_token_length++;
                }
        }

        /* parse a regular word */
        do {
                com_token[len] = c;
                data++;
                len++;
                com_token_length++;
                c = *data;
        } while (( c != ' ') && (!g_ascii_iscntrl(c)));

        com_token[len] = '\0';
        return data;
}


